const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();

    function findCenter(n, numEdges) {
        // Forward star representation for the tree
        const head = new Int32Array(n + 1).fill(-1);
        const to = new Int32Array(2 * numEdges);
        const next = new Int32Array(2 * numEdges);
        let edgeCount = 0;

        function addEdge(u, v) {
            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        for (let i = 0; i < numEdges; i++) {
            const u = nextInt();
            const v = nextInt();
            addEdge(u, v);
        }

        const dist = new Int32Array(n + 1);
        const parent = new Int32Array(n + 1);
        const queue = new Int32Array(n + 1);

        // First BFS from node 1
        function bfs(startNode) {
            dist.fill(-1);
            let headQ = 0, tailQ = 0;
            queue[tailQ++] = startNode;
            dist[startNode] = 0;
            parent[startNode] = 0;

            let farthestNode = startNode;

            while (headQ < tailQ) {
                const u = queue[headQ++];
                if (dist[u] > dist[farthestNode]) {
                    farthestNode = u;
                }

                for (let e = head[u]; e !== -1; e = next[e]) {
                    const v = to[e];
                    if (dist[v] === -1) {
                        dist[v] = dist[u] + 1;
                        parent[v] = u;
                        queue[tailQ++] = v;
                    }
                }
            }

            return farthestNode;
        }

        const nodeA = bfs(1);
        const nodeB = bfs(nodeA);

        // Path length is dist[nodeB]
        const pathLen = dist[nodeB];
        const stepsToCenter = Math.floor(pathLen / 2);

        let curr = nodeB;
        for (let i = 0; i < stepsToCenter; i++) {
            curr = parent[curr];
        }

        return curr;
    }

    const c1 = findCenter(N, N - 1);
    const c2 = findCenter(M, M - 1);

    process.stdout.write(c1 + " " + c2 + "\n");
}

solve();
